// `container` can be created here or use an existing DOM element\n    // the popover DOM is positioned independently of where the container exists\n    const container = document.createElement('div');\n    document.body.appendChild(container);\n\n    render(<PopoverApp anchor={thisAnchor} />, container);\n\n    return () => unmountComponentAtNode(container);\n  }, []);\n\n  return (\n    <div\n      dangerouslySetInnerHTML={{\n        __html: `\n  <button id=\"popoverAnchorButton\" class=\"ouiButton ouiButton--primary\">\n    <span class=\"ouiButton__content\">This is an HTML button</span>\n  </button>\n        `,\n      }}\n    />\n  );\n};\n"},function(e,n,t){"use strict";t.r(n),n.default='/*\n * SPDX-License-Identifier: Apache-2.0\n *\n * The OpenSearch Contributors require contributions made to\n * this file be licensed under the Apache-2.0 license or a\n * compatible open source license.\n *\n * Modifications Copyright OpenSearch Contributors. See\n * GitHub history for details.\n */\n\nimport React, { useState } from \'react\';\n\nimport {\n  OuiButton,\n  OuiCode,\n  OuiPanel,\n  OuiPopover,\n  OuiSpacer,\n} from \'../../../../src/components\';\n\nexport default () => {\n  const [isPopoverOpen, setIsPopoverOpen] = useState(false);\n  const [panelRef, setPanelRef] = useState(null);\n\n  const onButtonClick = () =>\n    setIsPopoverOpen((isPopoverOpen1) => !isPopoverOpen1);\n  const closePopover = () => setIsPopoverOpen(false);\n\n  const button = (\n    <OuiButton\n      iconType="arrowDown"\n      iconSide="right"\n      onClick={onButtonClick}\n      style={{ position: \'relative\', left: 50 }}>\n      Show constrained popover\n    </OuiButton>\n  );\n\n  return (\n    <OuiPanel panelRef={setPanelRef}>\n      <OuiPopover\n        button={button}\n        isOpen={isPopoverOpen}\n        closePopover={closePopover}\n        container={panelRef}>\n        <div>\n          Popover is positioned <OuiCode>downCenter</OuiCode> but constrained to\n          fit within the panel.\n        </div>\n      </OuiPopover>\n\n      {/* create adequate room for the popover */}\n      <OuiSpacer size="xxl" />\n      <OuiSpacer size="xxl" />\n    </OuiPanel>\n  );\n};\n'},function(e,n,t){"use strict";t.r(n),n.default="/*\n * SPDX-License-Identifier: Apache-2.0\n *\n * The OpenSearch Contributors require contributions made to\n * this file be licensed under the Apache-2.0 license or a\n * compatible open source license.\n *\n * Modifications Copyright OpenSearch Contributors. See\n * GitHub history for details.\n */\n\nimport React, { useState } from 'react';\n\nimport { OuiButton, OuiPopover } from '../../../../src/components';\n\nexport default () => {\n  const [isExampleShown, setIsExampleShown] = useState(false);\n  const [isPopoverOpen, setIsPopoverOpen] = useState(false);\n\n  const toggleExample = () =>\n    setIsExampleShown((isExampleShown) => !isExampleShown);\n\n  const onButtonClick = () =>\n    setIsPopoverOpen((isPopoverOpen) => !isPopoverOpen);\n  const closePopover = () => setIsPopoverOpen(false);\n\n  const button = (\n    <OuiButton\n      iconType=\"arrowDown\"\n      iconSide=\"right\"\n      onClick={onButtonClick}\n      fill>\n      Show fixed popover\n    </OuiButton>\n  );\n\n  return (\n    <React.Fragment>\n      <OuiButton onClick={toggleExample}>Toggle example</OuiButton>\n      {isExampleShown && (\n        <OuiPopover\n          button={button}\n          isOpen={isPopoverOpen}\n          closePopover={closePopover}\n          style={{ position: 'fixed', bottom: 50, right: 50, zIndex: 10 }}\n          repositionOnScroll={true}>\n          <div>This popover scrolls with the button element!</div>\n        </OuiPopover>\n      )}\n    </React.Fragment>\n  );\n};\n"},function(e,n,t){"use strict";t.r(n),n.default="/*\n * SPDX-License-Identifier: Apache-2.0\n *\n * The OpenSearch Contributors require contributions made to\n * this file be licensed under the Apache-2.0 license or a\n * compatible open source licen